"""Independent SOW check. usage: check.py <litware|northwind> <week> <schedule.csv> [runbook.md]"""
import sys, math
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
from collections import defaultdict
import pandas as pd

def erl_c(a,n):
    if n<=a: return 1.0
    term=1.0; s=1.0
    for k in range(1,n):
        term*=a/k; s+=term
    term*=a/n; top=term*n/(n-a)
    return top/(s+top)
def req_agents(vol,sec,aht,tgt,secs,cap=0.85):
    a=vol/sec*aht
    if a<=0: return 0
    n=max(1,math.ceil(a))
    while True:
        sl=1-erl_c(a,n)*math.exp(-(n-a)*secs/aht) if n>a else 0
        if sl>=tgt-1e-12 and a/n<=cap+1e-12: return n
        n+=1

SOW={
 'litware':dict(tz='Europe/London',grain=20,hours=(7,21),queues=['priority','standard','email'],
   sla={'priority':(.9,30),'standard':(.8,30),'email':(.8,300)},ratio=1.45,att=.95,end=True,floor={'priority':2},
   estart={'email':9},exc=True,
   agents='/app/data/agents/litware.csv'),
 'northwind':dict(tz='America/Chicago',grain=30,hours=(6,24),queues=['priority','standard'],
   sla={'priority':(.9,30),'standard':(.8,20)},ratio=1.57,att=.95,end=False,floor={},estart={},exc=False,
   agents='/app/data/agents/northwind.csv'),
}
client,week,schedf=sys.argv[1:4]
S=SOW[client]; z=ZoneInfo(S['tz']); g=timedelta(minutes=S['grain'])
yr,wk=week.split('-W'); mon=datetime.fromisocalendar(int(yr),int(wk),1)
st=datetime(mon.year,mon.month,mon.day,tzinfo=z).astimezone(timezone.utc)
nx=mon+timedelta(days=7); en=datetime(nx.year,nx.month,nx.day,tzinfo=z).astimezone(timezone.utc)
grid=[]; t=st
while t<en: grid.append(t); t+=g
# demand
fn=f"/app/data/{client}/export_{week}.csv"
d=pd.read_csv(fn)
col='interval_end_local' if S['end'] else 'interval_start_local'
u=pd.to_datetime(d[col]+d['utc_offset'],format='%Y-%m-%d %H:%M%z',utc=True)
if S['end']: u=u-pd.Timedelta(minutes=S['grain'])
d['t']=u
# northwind typos: 10:01 -> floor
d['t']=d['t'].dt.floor(f"{S['grain']}min")
dem={}
for r in d.itertuples():
    dem[(r.queue,r.t.to_pydatetime())]=(r.volume,r.aht_sec)
need={}
for q in S['queues']:
    for t in grid:
        v,a=dem.get((q,t),(0.0,0.0))
        tg,sc=S['sla'][q]
        need[(q,t)]=req_agents(v,S['grain']*60,a,tg,sc) if v>0 else 0
def lh(t): 
    l=t.astimezone(z); return l.hour+l.minute/60
exc=set()
if S['exc']:
    for (q,t),n in need.items():
        if q in S['estart'] and n>0 and lh(t)<S['estart'][q]: exc.add((q,t))
sc=pd.read_csv(schedf)
for c in ('segment_start_utc','segment_end_utc','break_start_utc'): sc[c]=pd.to_datetime(sc[c],utc=True)
ag=pd.read_csv(S['agents']).set_index('agent_id')
gross=defaultdict(int); brk=defaultdict(int)
for r in sc.itertuples():
    for t in grid:
        if r.segment_start_utc<=t<r.segment_end_utc: gross[(r.queue,t)]+=1
        if r.break_minutes>0 and r.break_start_utc<t+g and t<r.break_start_utc+timedelta(minutes=r.break_minutes): brk[(r.queue,t)]+=1
viol=defaultdict(list)
# attainment
ops=[t for t in grid if S['hours'][0]<=lh(t)<S['hours'][1]]
att={}; under=0.0
for q in S['queues']:
    m=n=0
    for t in ops:
        if (q,t) in exc: continue
        n+=1; net=gross[(q,t)]-brk[(q,t)]
        m+= net>=need[(q,t)]
    att[q]=m/n
    if att[q]<S['att']: viol['attainment'].append((q,att[q]))
for (q,t),n in need.items():
    if (q,t) in exc: continue
    under+=max(0,n-(gross[(q,t)]-brk[(q,t)]))*S['grain']/60
sched_h=(sc.segment_end_utc-sc.segment_start_utc).dt.total_seconds().sum()/3600
req_h=sum(need.values())*S['grain']/60
if sched_h>S['ratio']*req_h: viol['hours'].append((sched_h,req_h))
# shifts
sc['day']=sc.segment_start_utc.dt.tz_convert(z).dt.date
shifts={}
for (a,day),gp in sc.groupby(['agent_id','day']):
    gp=gp.sort_values('segment_start_utc')
    shifts[(a,day)]=gp
for (a,day),gp in shifts.items():
    c=ag.loc[a,'contract']; sk=ag.loc[a,'skills'].split(';')
    if len(gp)>1 and c!='PT': viol['split'].append((a,day))
    for q in gp.queue:
        if q not in sk: viol['skill'].append((a,q))
    if gp.queue.nunique()>1: pass
    s0=gp.segment_start_utc.iloc[0]; e0=gp.segment_end_utc.iloc[-1]
    # no crossing midnight
    if gp.segment_end_utc.dt.tz_convert(z).dt.date.iloc[-1]!=day and gp.segment_end_utc.dt.tz_convert(z).iloc[-1].time()!=datetime.min.time(): viol['midnight'].append((a,day))
    dur=(gp.segment_end_utc-gp.segment_start_utc).dt.total_seconds().sum()/3600
    nb=(gp.break_minutes>0).sum()
    if dur>=6 and nb!=1: viol['break_count'].append((a,day,nb))
    if dur<6 and nb!=0: viol['break_short'].append((a,day,nb))
    if nb:
        b=gp[gp.break_minutes>0].iloc[0]
        if b.break_minutes!=20: viol['break_len'].append((a,day))
        off=(b.break_start_utc-s0).total_seconds()/3600
        if not (2-1e-9<=off<=5+1e-9): viol['break_window'].append((a,day,off))
        if not (b.segment_start_utc<=b.break_start_utc and b.break_start_utc+timedelta(minutes=20)<=b.segment_end_utc): viol['break_in_seg'].append((a,day))
        q=gp.queue.iloc[0]
        # surplus rule: candidates = grain-aligned starts within window lying inside a segment
        cands=[t for t in grid if s0+timedelta(hours=2)<=t<=s0+timedelta(hours=5) and any(r.segment_start_utc<=t and t+timedelta(minutes=20)<=r.segment_end_utc for r in gp.itertuples())]
        sur=lambda t: gross[(q,t)]-need[(q,t)]
        if cands and sur(b.break_start_utc)<max(sur(t) for t in cands): viol['break_surplus'].append((a,day,b.break_start_utc,sur(b.break_start_utc),max(sur(t) for t in cands)))
    for r in gp.itertuples():
        if r.queue in S['estart'] and lh(r.segment_start_utc)<S['estart'][r.queue]: viol['email_start'].append((a,day))
# rest, hours, run, overlap
for a,gp in sc.groupby('agent_id'):
    gp=gp.sort_values('segment_start_utc')
    c=ag.loc[a,'contract']
    h=(gp.segment_end_utc-gp.segment_start_utc).dt.total_seconds().sum()/3600
    if h>{'FT':40,'PT':24}[c]+1e-9: viol['weekly_hours'].append((a,h))
    if (gp.segment_start_utc.values[1:]<gp.segment_end_utc.values[:-1]).any(): viol['overlap'].append(a)
    sh=[(x.segment_start_utc.iloc[0],x.segment_end_utc.iloc[-1]) for _,x in sorted(((k[1],v) for k,v in shifts.items() if k[0]==a),key=lambda kv:kv[1].segment_start_utc.iloc[0])]
    for (s1,e1),(s2,e2) in zip(sh,sh[1:]):
        if s2-e1<timedelta(hours=11): viol['rest'].append((a,e1,s2))
    days=sorted(k[1] for k in shifts if k[0]==a); run=1
    for x,y in zip(days,days[1:]):
        run=run+1 if (y-x).days==1 else 1
        if run>5: viol['run'].append(a)
for q,fl in S['floor'].items():
    for t in ops:
        if gross[(q,t)]<fl: viol['floor'].append((q,t,gross[(q,t)]))
print(f"{client} {week}: intervals {len(grid)} att {({q:round(v,4) for q,v in att.items()})} sched_h {sched_h:.1f} req_h {req_h:.1f} ratio {sched_h/req_h:.3f} under {under:.2f} agents {sc.agent_id.nunique()} exceptions {len(exc)}")
print("VIOLATIONS:",{k:(len(v),v[:3]) for k,v in viol.items()} or "none")
if len(sys.argv)>4:
    import re
    txt=open(sys.argv[4]).read()
    print(txt[:1500])
E
